export type SchemaBuffers<F extends Record<string, ScalarKind>> = {
    readonly [K in keyof F]: TypedBuffer<F[K]>;
} & {

    raws(): {
        readonly [K in keyof F]: Buffer<F[K]>;
    };
    destroy(): void;
};

